-- Seed catalogue of well-known strains. Photos are freely licensed Wikimedia
-- Commons files whose uploaders identify the strain; null = no genuine photo.
-- Autoflowers: weeks are the bloom phase only. Idempotent (upsert on slug).

insert into public.strains
  (slug, name, breeder, dominance, flowering, flowering_weeks_min, flowering_weeks_max, description, image_url, image_credit, created_by, approved)
values
  ('northern-lights', 'Northern Lights', 'Sensi Seeds', 'indica', 'photo', 7, 8,
   'A classic Afghan-heritage indica, compact and bushy with short internodes. Forgiving of beginner mistakes, resilient to pests and a steady producer of dense, resinous buds. Keeps a low profile in small tents.',
   'https://upload.wikimedia.org/wikipedia/commons/thumb/b/b3/Northern_lights.JPG/960px-Northern_lights.JPG',
   'Sativaindica · CC BY 3.0 (Wikimedia Commons)', null, true),
  ('white-widow', 'White Widow', 'Green House Seeds', 'hybrid', 'photo', 8, 9,
   'A Brazilian sativa × South Indian indica cross from the 1990s Dutch scene, known for buds coated in white trichomes. Medium height, sturdy branching and an easy, predictable flowering.',
   'https://upload.wikimedia.org/wikipedia/commons/thumb/3/31/White_Widow_%28Green_House_Seeds%29_01.jpg/960px-White_Widow_%28Green_House_Seeds%29_01.jpg',
   'Yuri Che · CC BY-SA 3.0 (Wikimedia Commons)', null, true),
  ('skunk-1', 'Skunk #1', 'Sacred Seeds', 'hybrid', 'photo', 7, 8,
   'One of the first stabilised hybrids (Afghani × Acapulco Gold × Colombian Gold), parent of countless modern strains. Uniform, vigorous and fast, with a strong earthy aroma that calls for good carbon filtering.',
   null, null, null, true),
  ('ak-47', 'AK-47', 'Serious Seeds', 'hybrid', 'photo', 8, 9,
   'Serious Seeds’ 1992 F1 hybrid of Colombian, Mexican, Thai and Afghani stock, roughly 65:35 sativa/indica. Medium height with a Christmas-tree shape and a high calyx-to-leaf ratio, giving compact, resinous buds that are quick to trim. Easy for beginners; spicy-sweet odour in late bloom.',
   null, null, null, true),
  ('blue-dream', 'Blue Dream', 'Various', 'sativa', 'photo', 9, 10,
   'A Californian Blueberry × Haze cross. Tall and vigorous with long branches that respond well to topping and SCROG. Sweet berry aroma; likes plenty of light and space.',
   'https://upload.wikimedia.org/wikipedia/commons/thumb/8/88/Blooming_Blue_Dream.jpg/960px-Blooming_Blue_Dream.jpg',
   'My 420 Tours · CC BY-SA 4.0 (Wikimedia Commons)', null, true),
  ('girl-scout-cookies', 'Girl Scout Cookies', 'Cookie Fam', 'hybrid', 'photo', 9, 10,
   'OG Kush × Durban Poison from the San Francisco Bay Area, often shortened to GSC. Moderate yields of dense, frosty buds that can turn purple in cool nights. Benefits from defoliation and steady humidity.',
   null, null, null, true),
  ('gorilla-glue-4', 'Gorilla Glue #4', 'GG Strains', 'hybrid', 'photo', 8, 9,
   'Chem’s Sister × Sour Dubb × Chocolate Diesel, named for its extremely sticky resin. Stretches a lot in early bloom, so plan height and train early. Heavy, chunky colas with a diesel-pine smell.',
   'https://upload.wikimedia.org/wikipedia/commons/thumb/9/90/420Natural_GG-4_Bud_on_desk.jpg/960px-420Natural_GG-4_Bud_on_desk.jpg',
   'HerrBlaze · CC BY-SA 4.0 (Wikimedia Commons)', null, true),
  ('sour-diesel', 'Sour Diesel', 'Various', 'sativa', 'photo', 10, 11,
   'An East Coast clone-only classic with Chemdog ancestry and a sharp fuel aroma. Lanky and tall with a long flowering time; rewards training and patience. Needs strong odour control.',
   'https://upload.wikimedia.org/wikipedia/commons/thumb/e/ed/Cannabis_%28Sour_Diesel%29_Flower.jpg/960px-Cannabis_%28Sour_Diesel%29_Flower.jpg',
   'Alapoet · CC BY 3.0 (Wikimedia Commons)', null, true),
  ('og-kush', 'OG Kush', 'Various', 'hybrid', 'photo', 8, 9,
   'The West Coast cornerstone behind many modern hybrids, with an earthy pine and lemon scent. Medium height, prone to powdery mildew in humid rooms, so keep air moving and leaves thinned.',
   'https://upload.wikimedia.org/wikipedia/commons/6/63/Kush-trichome-closeup.jpg',
   'Derrylwc · Public domain (Wikimedia Commons)', null, true),
  ('jack-herer', 'Jack Herer', 'Sensi Seeds', 'sativa', 'photo', 8, 10,
   'A Haze × Northern Lights #5 × Shiva Skunk hybrid named after the hemp activist. Tall, open structure with spicy pine aromas. Phenotypes vary, so selecting a good mother pays off.',
   'https://upload.wikimedia.org/wikipedia/commons/thumb/9/92/KOROVA_OR_FLOWER_WE_OG_JACK_HERER_MACRO_1080.png/960px-KOROVA_OR_FLOWER_WE_OG_JACK_HERER_MACRO_1080.png',
   'Forcefield21 · CC BY-SA 4.0 (Wikimedia Commons)', null, true),
  ('super-lemon-haze', 'Super Lemon Haze', 'Green House Seeds', 'sativa', 'photo', 9, 10,
   'Lemon Skunk × Super Silver Haze with a bright citrus aroma. Stretches strongly after the flip and appreciates a net or stakes. Buds are long and frosty rather than dense.',
   null, null, null, true),
  ('amnesia-haze', 'Amnesia Haze', 'Various', 'sativa', 'photo', 10, 12,
   'A Haze-dominant favourite of Dutch coffeeshops with a citrus-earthy aroma. Very tall and slow to finish; best suited to growers with headroom and a patient schedule.',
   'https://upload.wikimedia.org/wikipedia/commons/thumb/8/85/Amnesia_variedad_de_cannabis_%281%29.jpg/960px-Amnesia_variedad_de_cannabis_%281%29.jpg',
   'El Mono Español · CC BY-SA 4.0 (Wikimedia Commons)', null, true),
  ('durban-poison', 'Durban Poison', 'Various', 'sativa', 'photo', 8, 9,
   'A pure South African landrace sativa with a sweet anise scent. Tall with large leaves and big trichome heads, and unusually quick for a sativa. Handles outdoor sun well.',
   null, null, null, true),
  ('granddaddy-purple', 'Granddaddy Purple', 'Ken Estes', 'indica', 'photo', 8, 9,
   'Purple Urkle × Big Bud from California, famous for deep purple buds and a grape-berry aroma. Compact and bulky; colours come out best with cooler night temperatures late in bloom.',
   null, null, null, true),
  ('purple-kush', 'Purple Kush', 'Various', 'indica', 'photo', 8, 9,
   'A pure indica from Hindu Kush and Purple Afghani lines. Short, wide plants with tight internodes and dense, often purple-hued flowers. Good choice for low-ceiling grows.',
   'https://upload.wikimedia.org/wikipedia/commons/0/0a/Flowers%28Purple_Kush%29.jpg',
   'hexthat · CC BY 3.0 (Wikimedia Commons)', null, true),
  ('bubba-kush', 'Bubba Kush', 'Various', 'indica', 'photo', 8, 9,
   'A heavy indica with a sweet hashy, coffee-like scent. Stays short and stocky with chunky buds. Watch humidity late in flower because of the dense structure.',
   'https://upload.wikimedia.org/wikipedia/commons/thumb/3/36/Bubba_Kush.jpg/960px-Bubba_Kush.jpg',
   'Coaster420 · Public domain (Wikimedia Commons)', null, true),
  ('wedding-cake', 'Wedding Cake', 'Seed Junky Genetics', 'hybrid', 'photo', 8, 9,
   'Triangle Kush × Animal Mints, also sold as Triangle Mints #23. Indica-leaning with a sweet vanilla-dough aroma and heavy resin. Responds well to topping and an even canopy.',
   'https://upload.wikimedia.org/wikipedia/commons/thumb/3/3f/Wedding_Cake_Cannabis_Strain.jpg/960px-Wedding_Cake_Cannabis_Strain.jpg',
   'Forcefield21 · CC BY-SA 4.0 (Wikimedia Commons)', null, true),
  ('gelato', 'Gelato', 'Cookie Fam', 'hybrid', 'photo', 8, 9,
   'Sunset Sherbet × Thin Mint GSC from the Bay Area. Dessert-like sweet aroma and colourful, dense buds. Medium height with moderate yields; quality benefits from a slow dry and cure.',
   null, null, null, true),
  ('zkittlez', 'Zkittlez', 'Terp Hogz / 3rd Gen Family', 'indica', 'photo', 8, 9,
   'Grape Ape × Grapefruit with a third parent kept private, known for a candy-fruit terpene profile. Medium-sized, manageable plants; terpenes shine with a cool, slow drying room.',
   null, null, null, true),
  ('critical-mass', 'Critical Mass', 'Mr. Nice Seeds', 'indica', 'photo', 7, 8,
   'Afghani × Skunk #1 bred for very heavy colas. Branches often need support in late bloom, and the dense buds need good airflow and low humidity to avoid mould.',
   null, null, null, true),
  ('blueberry', 'Blueberry', 'DJ Short', 'indica', 'photo', 8, 9,
   'A 1970s-rooted indica built from Thai and Afghani lines, prized for its berry aroma. Medium height, often shows blue and purple tones late in flower. Easygoing and stable.',
   'https://upload.wikimedia.org/wikipedia/commons/thumb/a/ad/Blueberry_%28Dutch_Passion%29_01.jpg/960px-Blueberry_%28Dutch_Passion%29_01.jpg',
   'Yuri Che · CC BY-SA 3.0 (Wikimedia Commons)', null, true),
  ('trainwreck', 'Trainwreck', 'Various', 'sativa', 'photo', 8, 10,
   'A Northern California classic of Mexican, Thai and Afghani descent with a sharp lemon-pine aroma. Fast-growing and tall; benefits from early topping and a trellis.',
   'https://upload.wikimedia.org/wikipedia/commons/thumb/b/b5/Trainwreck_Strain.jpg/960px-Trainwreck_Strain.jpg',
   'Coaster420 · Public domain (Wikimedia Commons)', null, true),
  ('hindu-kush', 'Hindu Kush', 'Various', 'indica', 'photo', 7, 8,
   'A landrace indica from the mountains between Afghanistan and Pakistan, the root of most Kush lines. Short, broad-leaved and hardy, with a resinous, earthy-sweet aroma.',
   null, null, null, true),
  ('super-silver-haze', 'Super Silver Haze', 'Green House Seeds', 'sativa', 'photo', 10, 11,
   'Skunk × Northern Lights × Haze, a multiple cup winner of the late 1990s. Tall with long, frosty colas and a citrus-spice aroma. Needs headroom and a longer flowering window.',
   'https://upload.wikimedia.org/wikipedia/commons/thumb/6/65/Kolkata-Kut.jpg/960px-Kolkata-Kut.jpg',
   'Psychonaught · Public domain (Wikimedia Commons)', null, true),
  ('green-crack', 'Green Crack', 'Various', 'sativa', 'photo', 7, 9,
   'A Skunk #1 descendant with a tangy mango aroma, sometimes sold as Green Cush. Quick for a sativa and productive indoors or out; stretches moderately after the flip.',
   'https://upload.wikimedia.org/wikipedia/commons/thumb/1/1d/Green_Crack.jpg/960px-Green_Crack.jpg',
   'Psychonaught · Public domain (Wikimedia Commons)', null, true),
  ('acapulco-gold', 'Acapulco Gold', 'Various', 'sativa', 'photo', 9, 11,
   'A Mexican landrace sativa named for the golden hue its buds can take on. Tall and airy with a long bloom; thrives in warm, sunny climates and strong indoor light.',
   'https://upload.wikimedia.org/wikipedia/commons/thumb/9/9b/Indoor_grown_Acapulco_Gold_in_Final_Stages_of_Flowering_1.jpg/960px-Indoor_grown_Acapulco_Gold_in_Final_Stages_of_Flowering_1.jpg',
   'KindHorta · CC0 (Wikimedia Commons)', null, true),
  ('purple-haze', 'Purple Haze', 'Various', 'sativa', 'photo', 8, 10,
   'A Haze-family sativa popularised in the 1960s and 70s, with purple-tinged buds and a sweet, earthy scent. Tall and open; purple colouring shows more with cool nights.',
   'https://upload.wikimedia.org/wikipedia/commons/thumb/7/78/Fleurs_coup%C3%A9es_de_Purple_Haze.JPG/960px-Fleurs_coup%C3%A9es_de_Purple_Haze.JPG',
   'Mr TM · CC BY-SA 3.0 (Wikimedia Commons)', null, true),
  ('white-rhino', 'White Rhino', 'Green House Seeds', 'indica', 'photo', 8, 9,
   'A White Widow offspring with Afghani and Brazilian roots. Short, heavy-yielding and resin-rich; colas get dense enough that branch support and good airflow help.',
   'https://upload.wikimedia.org/wikipedia/commons/thumb/e/e4/White_Rhino_Dub_Macro.JPG/960px-White_Rhino_Dub_Macro.JPG',
   'CannabisQ · CC BY 3.0 (Wikimedia Commons)', null, true),
  ('cheese', 'Cheese', 'Various', 'hybrid', 'photo', 8, 9,
   'A UK Skunk #1 phenotype made famous by the Exodus collective, named for its pungent, savoury aroma. Easy to grow with good yields; serious carbon filtering is a must.',
   'https://upload.wikimedia.org/wikipedia/commons/thumb/e/ed/Cannabis_Cheese_%2816407627263%29.jpg/960px-Cannabis_Cheese_%2816407627263%29.jpg',
   'Cannabis Pictures · CC BY 2.0 (Wikimedia Commons)', null, true),
  ('lowryder', 'Lowryder', 'The Joint Doctor', 'hybrid', 'auto', 5, 6,
   'The first widely available autoflower, built from Northern Lights #2, William’s Wonder and a ruderalis line. Tiny plants that finish around 8–9 weeks from seed regardless of light schedule.',
   'https://upload.wikimedia.org/wikipedia/commons/thumb/f/f1/Lowryder.JPG/960px-Lowryder.JPG',
   'Sativaindica · CC BY 3.0 (Wikimedia Commons)', null, true),
  ('northern-lights-auto', 'Northern Lights Auto', 'Various', 'indica', 'auto', 6, 7,
   'Northern Lights crossed with ruderalis. Compact and very beginner-friendly, usually ready about 9–10 weeks from seed. Avoid heavy training; light LST works best.',
   null, null, null, true),
  ('amnesia-haze-auto', 'Amnesia Haze Auto', 'Various', 'sativa', 'auto', 7, 8,
   'An autoflowering version of the Haze classic. Taller than most autos and slower, often 11–12 weeks from seed. Give it a final pot from the start to avoid transplant stress.',
   null, null, null, true),
  ('gorilla-glue-auto', 'Gorilla Glue Auto', 'Various', 'hybrid', 'auto', 6, 7,
   'Gorilla Glue #4 genetics with ruderalis for automatic flowering, typically 9–10 weeks from seed. Keeps the sticky resin of the original in a smaller frame.',
   null, null, null, true),
  ('blueberry-auto', 'Blueberry Auto', 'Various', 'indica', 'auto', 6, 7,
   'A compact autoflower with Blueberry’s fruity aroma and frequent purple hues. Usually done 9–10 weeks from seed; a good pick for balconies and small tents.',
   null, null, null, true),
  ('afghani-kush', 'Afghani Kush', 'Various', 'indica', 'photo', 7, 8,
   'An Afghan indica line from the Hindu Kush, grown for generations for hash. Short and stocky with broad, dark leaves and a thick resin coat. Finishes fast and copes well with cooler nights.',
   'https://upload.wikimedia.org/wikipedia/commons/thumb/3/37/Afghani_Kush.jpg/960px-Afghani_Kush.jpg',
   'Coaster420 · Public domain (Wikimedia Commons)', null, true),
  ('g13', 'G-13', 'Various', 'indica', 'photo', 8, 9,
   'A legendary Afghani-type clone surrounded by stories of a US government research programme. Medium height with heavy, resinous buds and an earthy, piney aroma. Parent of G13 Haze and many later crosses.',
   'https://upload.wikimedia.org/wikipedia/commons/thumb/a/a0/G-13.jpg/960px-G-13.jpg',
   'Psychonaught · Public domain (Wikimedia Commons)', null, true),
  ('gods-gift', 'God’s Gift', 'Various', 'indica', 'photo', 8, 9,
   'A Californian cross of Granddaddy Purple and OG Kush. Compact, bushy plants with dense buds that often show purple tones late in bloom; grape and citrus notes. Keep humidity low around the tight colas.',
   'https://upload.wikimedia.org/wikipedia/commons/thumb/4/44/Gods_Gift.jpg/960px-Gods_Gift.jpg',
   'Coaster420 · Public domain (Wikimedia Commons)', null, true),
  ('do-si-dos', 'Do-Si-Dos', 'Archive Seed Bank', 'hybrid', 'photo', 8, 10,
   'OGKB (a GSC phenotype) × Face Off OG, leaning indica. Frosty, lime-green buds with a sweet, earthy-floral scent. Moderate stretch; responds well to topping and an even canopy.',
   'https://upload.wikimedia.org/wikipedia/commons/thumb/8/8c/Dosidos_Cannabis_Strain%2C_grown_by_Archive.jpg/960px-Dosidos_Cannabis_Strain%2C_grown_by_Archive.jpg',
   'Forcefield21 · CC BY-SA 4.0 (Wikimedia Commons)', null, true),
  ('early-skunk', 'Early Skunk', 'Sensi Seeds', 'hybrid', 'photo', 7, 9,
   'Skunk #1 combined with Early Pearl for an earlier outdoor harvest in cooler climates. Vigorous with a sativa-leaning frame and long, chunky colas. Indoors it stays predictable and easy.',
   'https://upload.wikimedia.org/wikipedia/commons/thumb/4/46/Flowering_Early_Skunk_Cannabis_Sativa.jpg/960px-Flowering_Early_Skunk_Cannabis_Sativa.jpg',
   'Botanica · CC BY 4.0 (Wikimedia Commons)', null, true),
  ('white-skunk', 'White Skunk', 'Sensi Seeds', 'hybrid', 'photo', 7, 9,
   'A Skunk-based hybrid from Sensi Seeds’ White Label range, selected for a heavy coat of white trichomes. Easy, uniform growth and a classic sweet-sour Skunk aroma; good carbon filtering helps.',
   'https://upload.wikimedia.org/wikipedia/commons/thumb/1/14/Flowering_White_Skunk_Cannabis_Sativa.jpg/960px-Flowering_White_Skunk_Cannabis_Sativa.jpg',
   'Botanica · CC BY 4.0 (Wikimedia Commons)', null, true),
  ('grapefruit', 'Grapefruit', 'Various', 'sativa', 'photo', 7, 8,
   'A Cinderella 99 descendant with a bright grapefruit-citrus aroma. Sativa-leaning but quick and fairly compact, so it suits smaller indoor spaces. Expect some stretch in the first weeks of bloom.',
   'https://upload.wikimedia.org/wikipedia/commons/thumb/4/4b/Cannabis_Grapefruit_%2816974515889%29.jpg/960px-Cannabis_Grapefruit_%2816974515889%29.jpg',
   'Cannabis Pictures · CC BY 2.0 (Wikimedia Commons)', null, true),
  ('lemon-kush', 'Lemon Kush', 'Various', 'hybrid', 'photo', 8, 9,
   'A Kush-family hybrid with a sharp lemon-zest scent over an earthy base. Medium height with sturdy branches and dense buds. Keep air moving through the canopy to protect the tight flowers.',
   'https://upload.wikimedia.org/wikipedia/commons/thumb/1/10/Lemon_kush%2C_day_114%2C_flower_86_%285182567301%29.jpg/960px-Lemon_kush%2C_day_114%2C_flower_86_%285182567301%29.jpg',
   'Mark · CC BY 2.0 (Wikimedia Commons)', null, true),
  ('orange-crush', 'Orange Crush', 'BC Bud Depot', 'hybrid', 'photo', 8, 9,
   'California Orange × Blueberry from British Columbia, with a sweet orange-citrus aroma. Medium height and sativa-leaning in shape; colas are long rather than very dense, which helps against mould.',
   'https://upload.wikimedia.org/wikipedia/commons/thumb/0/0f/Orange_Crush1.jpg/960px-Orange_Crush1.jpg',
   'Murken · Public domain (Wikimedia Commons)', null, true),
  ('presidential-kush', 'Presidential Kush', 'Various', 'hybrid', 'photo', 8, 9,
   'An OG Kush descendant, also sold as Presidential OG, with a lemon-pine and fuel aroma. Indica-leaning with dense, frosty buds. Like most OGs it appreciates good airflow and a steady environment.',
   'https://upload.wikimedia.org/wikipedia/commons/thumb/d/d2/Presidential_Kush_Cannabis_Strain.jpg/960px-Presidential_Kush_Cannabis_Strain.jpg',
   'Forcefield21 · CC BY-SA 4.0 (Wikimedia Commons)', null, true),
  ('pure-kush', 'Pure Kush', 'Various', 'indica', 'photo', 8, 9,
   'An indica built on Hindu Kush genetics, with an earthy, hashy scent. Compact and broad-leaved with heavy main colas. A straightforward grow that suits small tents and short ceilings.',
   'https://upload.wikimedia.org/wikipedia/commons/thumb/1/1c/Pure_Kush.jpg/960px-Pure_Kush.jpg',
   'Coaster420 · Public domain (Wikimedia Commons)', null, true),
  ('purple-urkle', 'Purple Urkle', 'Various', 'indica', 'photo', 8, 9,
   'A Mendocino purple clone from California and a parent of Granddaddy Purple. Short and bushy with grape-berry aromas and buds that turn deep purple, especially with cooler nights. Yields are modest.',
   'https://upload.wikimedia.org/wikipedia/commons/thumb/4/4b/Purp_ErK.jpg/960px-Purp_ErK.jpg',
   'Psychonaught · Public domain (Wikimedia Commons)', null, true),
  ('super-skunk', 'Super Skunk', 'Sensi Seeds', 'indica', 'photo', 7, 8,
   'Skunk #1 crossed back to an Afghani indica for more weight and resin. Stocky, fast and productive, with a very strong skunky odour. Serious carbon filtering is a must indoors.',
   'https://upload.wikimedia.org/wikipedia/commons/thumb/7/73/Super_Skunk.jpg/960px-Super_Skunk.jpg',
   'Nickel Bag of Funk · CC BY 2.0 (Wikimedia Commons)', null, true),
  ('white-dwarf', 'White Dwarf', 'Buddha Seeds', 'hybrid', 'auto', 6, 7,
   'A small autoflower built from White Widow and ruderalis genetics, covered in white resin. Usually around 9–10 weeks from seed and rarely taller than a metre. Avoid topping; gentle LST works best.',
   'https://upload.wikimedia.org/wikipedia/commons/5/57/Whitedwarf_foto.png',
   'Ankari80 · CC BY-SA 3.0 (Wikimedia Commons)', null, true),
  ('punto-rojo', 'Punto Rojo', 'Various', 'sativa', 'photo', 12, 14,
   'A Colombian landrace sativa whose name, “red dot”, comes from its reddish pistils. Very tall and slow with airy buds and a long bloom. Best outdoors in warm climates or indoors with lots of headroom.',
   'https://upload.wikimedia.org/wikipedia/commons/a/a9/Colombia_Punto_Rojo_%28detail%29.jpg',
   'El Mono Español · CC BY-SA 4.0 (Wikimedia Commons)', null, true),
  ('motavation', 'Motavation', 'Serious Seeds', 'indica', 'photo', 8, 9,
   'A Serious Seeds indica-dominant hybrid bred for uniform plants and heavy, resinous colas. Medium height with short side branches; it suits a sea of green. Watch humidity late in bloom.',
   'https://upload.wikimedia.org/wikipedia/commons/thumb/d/de/MOTAVATION_EN_FLORACION.jpg/960px-MOTAVATION_EN_FLORACION.jpg',
   'Manutara · CC BY-SA 3.0 (Wikimedia Commons)', null, true),
  ('zookies', 'Zookies', 'Oni Seed Co.', 'hybrid', 'photo', 8, 9,
   'Animal Cookies × Gorilla Glue #4, leaning indica. Dense, sticky buds with a sweet, nutty-diesel aroma. Stretches moderately after the flip; train early and support the heavier tops.',
   'https://upload.wikimedia.org/wikipedia/commons/thumb/0/0a/Zookies-IndicaDominate-AnimalCookies%26GG-4-20181111.jpg/960px-Zookies-IndicaDominate-AnimalCookies%26GG-4-20181111.jpg',
   'Vito619 · CC BY-SA 4.0 (Wikimedia Commons)', null, true),
  ('malawi-gold', 'Malawi Gold', 'Various', 'sativa', 'photo', 12, 16,
   'An African landrace sativa from Malawi, traditionally sun-grown and sold as “chamba”. Tall, thin-leaved and slow to finish, with long, airy colas. Rewarding outdoors in long, warm seasons.',
   'https://upload.wikimedia.org/wikipedia/commons/thumb/f/fe/Malawi_Gold_2023_10.jpg/960px-Malawi_Gold_2023_10.jpg',
   'Stevef199 · CC BY-SA 4.0 (Wikimedia Commons)', null, true),
  ('white-tahoe-cookies', 'White Tahoe Cookies', 'Cookie Fam', 'hybrid', 'photo', 9, 10,
   'Tahoe OG × GSC × The White, from the Cookies family of strains. Indica-leaning with dense, frosty buds and a sweet, earthy-gas aroma. Moderate yields; defoliation helps light reach the lower sites.',
   'https://upload.wikimedia.org/wikipedia/commons/thumb/b/b0/White_Tahoe_Cookie.jpg/960px-White_Tahoe_Cookie.jpg',
   'Beeblebrox · CC BY-SA 4.0 (Wikimedia Commons)', null, true),
  ('strawberry-cough', 'Strawberry Cough', 'Kyle Kushman', 'sativa', 'photo', 9, 10,
   'A sativa-leaning strain with a sweet strawberry aroma, usually traced to Strawberry Fields and Haze. Tall and fairly open; top early and give it room to stretch. Terpenes are best with a slow cure.',
   null, null, null, true),
  ('pineapple-express', 'Pineapple Express', 'G13 Labs', 'hybrid', 'photo', 8, 9,
   'Trainwreck × Hawaiian with a tropical pineapple-cedar aroma. Sativa-leaning, vigorous and productive indoors or out. Expect a fair stretch after the flip and plan for a trellis.',
   null, null, null, true),
  ('chemdawg', 'Chemdawg', 'Various', 'hybrid', 'photo', 9, 10,
   'A 1990s East Coast clone with a pungent diesel-chemical scent, ancestor of Sour Diesel and a parent of many OG lines. Lanky with a fair stretch; needs training and strong odour control.',
   null, null, null, true),
  ('runtz', 'Runtz', 'Cookies / Runtz', 'hybrid', 'photo', 8, 9,
   'Zkittlez × Gelato with a sweet, candy-like fruit aroma. Medium-sized plants with dense, colourful buds. Yields are moderate; a slow dry and cure keep the terpenes intact.',
   null, null, null, true),
  ('bruce-banner', 'Bruce Banner', 'Dark Horse Genetics', 'hybrid', 'photo', 8, 9,
   'OG Kush × Strawberry Diesel from Colorado, known for large, resin-heavy colas. Vigorous and sativa-leaning with a strong stretch; topping and a trellis keep the canopy manageable.',
   null, null, null, true),
  ('tangerine-dream', 'Tangerine Dream', 'Barney’s Farm', 'sativa', 'photo', 10, 11,
   'G13 × Afghani × Neville’s A5 Haze with a sweet tangerine-citrus aroma. Tall with long, heavy colas that often need support. Give it headroom and a longer bloom than most hybrids.',
   null, null, null, true),
  ('sunset-sherbet', 'Sunset Sherbet', 'Sherbinski', 'hybrid', 'photo', 8, 9,
   'GSC × Pink Panties from San Francisco, indica-leaning with a sweet, fruity-dessert aroma. Compact to medium height with dense buds that can show purple. Low humidity late in bloom protects the colas.',
   null, null, null, true)
on conflict (slug) do update set
  name = excluded.name,
  breeder = excluded.breeder,
  dominance = excluded.dominance,
  flowering = excluded.flowering,
  flowering_weeks_min = excluded.flowering_weeks_min,
  flowering_weeks_max = excluded.flowering_weeks_max,
  description = excluded.description,
